from django.conf import settings
from django.db import models
from ..models import TimeStampedModel,WorkflowDefinition
class ChangePlan(TimeStampedModel):workflow=models.ForeignKey(WorkflowDefinition,related_name='change_plans',on_delete=models.CASCADE);name=models.CharField(max_length=180);release=models.CharField(max_length=80);status=models.CharField(max_length=30,default='draft');sponsors=models.JSONField(default=list);stakeholders=models.JSONField(default=list);readiness_score=models.DecimalField(max_digits=5,decimal_places=2,null=True);owner=models.ForeignKey(settings.AUTH_USER_MODEL,null=True,on_delete=models.SET_NULL)
class ChangeCommunication(TimeStampedModel):plan=models.ForeignKey(ChangePlan,related_name='communications',on_delete=models.CASCADE);audience=models.JSONField(default=dict);channel=models.CharField(max_length=80);message=models.TextField();scheduled_at=models.DateTimeField(null=True,blank=True);status=models.CharField(max_length=30,default='draft')
class TrainingAsset(TimeStampedModel):plan=models.ForeignKey(ChangePlan,related_name='training_assets',on_delete=models.CASCADE);title=models.CharField(max_length=180);asset_type=models.CharField(max_length=60);content_reference=models.CharField(max_length=255);required=models.BooleanField(default=True)
class AdoptionMetric(models.Model):plan=models.ForeignKey(ChangePlan,related_name='adoption_metrics',on_delete=models.CASCADE);name=models.CharField(max_length=120);value=models.DecimalField(max_digits=14,decimal_places=4);unit=models.CharField(max_length=40);recorded_at=models.DateTimeField(auto_now_add=True)
